Given a poset system $(X^p)$, we define the \emph{indicator set}

\[
P_x = \{ p \in P \mid x \in X^p \}
\]

of $x \in X$.

By monotonicity, this is an up-closed (or Alexandrov-open) subset of~$P$.

\label{ex:subsystem}
    Let $(X^p)$ be a $P$-system in~$X$ and let $A \subseteq P$.

    Then $(X^a) = (X^a \mid a \in A)$ is an $A$-system in~$X$. It is also an $A$-system in~$X^A$ (or any set containing $X^A$).

\label{ex:tautological-P-system}
    For any poset $P$, the formula
    \[
    P^p = \mathrm{Cone}(p) = {\downarrow}{\{}p\}
    \]
    defines a $P$-system in~$P$. We call this the \emph{tautological $P$-system}.

\label{prop:push-square}
    Suppose we have a commutative square of poset maps:
    \[
    \xymatrix{
    P
        \ar[r]^-{\phi}
        \ar[d]_-{\alpha}
    &
    Q
        \ar[d]^-{\beta}
    \\
    R
        \ar[r]^-{\psi}
    &
    S
    }
    \]
     Let $f : X \to Y$ be a $\phi$-map with respect to poset systems $(X^p)$, $(Y^q)$. Then:

    (1) $\phi$ restricts to a map $\alpha/r \to \beta/\psi(r)$ between Quillen fibers, for all $r \in R$.

    (2) $f$ is a $\psi$-map with respect to the pushforward poset systems $(X^{\alpha/r})$, $(Y^{\beta/s})$.

\label{def:separated}
    A $P$-system $(X^p)$ is \emph{separated}\footnote{ 
    The choice of the word `separated' is motivated by the observation in Example~\ref{ex:minimal-disjoint}.}  

    if each indicator set $P_x$ has a smallest element. Writing $p_x$ for the smallest element, it follows that $P_x = {\uparrow}{\{p_x\}}$.

\label{ex:minimal-disjoint}
    Let $X^P$ be a $P$-complex. For \emph{minimal} elements $a \in P$, the sets $X^a$ are mutually disjoint. To see this, note that for any $x \in X$ there is at most one element of the indicator set $P_x$ that can be minimal in~$P$, namely the smallest element~$p_x$.

    This observation motivates the word `separated'.

\label{ex:V-complex}
    Let $V = (1 > 0 < 2)$ denote the V-shaped 3-element poset with a smallest element~0 and two maximal elements $1,2$.

    A $V$-system in a set~$X$ is specified by subsets $X^0, X^1, X^2 \subseteq X$ with $X^0 \subseteq X^1$ and $X^0 \subseteq X^2$. If it is separated then

    \begin{align*}
        X^0 &= \{ x \in X \mid p_x = 0 \} 
        \\
        X^1 &= \{ x \in X \mid p_x = 0 \text{\;or\;} 1 \} 
        \\
        X^2 &= \{ x \in X \mid p_x = 0 \text{\;or\;} 2 \} 
    \end{align*}

    from which it follows that $X = X^1 \cup X^2$ and $X^0 = X^1 \cap X^2$.

    In this way, we see that a $V$-complex is the `same thing' as a set $X$ with a cover by two subsets $X^1, X^2$.

\label{prop:bounded-lattice-map}
    Let $(X^p)$ be a $P$-system in a set~$X$. Consider the following properties:

    \begin{enumerate}
        \item
        $(X^p)$ is separated.

        \medskip
        \item
        The mapping $A \mapsto X^A$ defines a bounded-lattice homomorphism 
        $\mathrm{Cl}(P) \to \mathcal{P}(X)$.

    \end{enumerate}
     Then (1) $\Rightarrow$ (2). If $P$ is finite (or, more generally, well founded\,\footnote{ 
        A poset is well founded if every nonempty subset has a minimal element.
        }) then (2) $\Rightarrow$ (1).

\label{prop:classifying-map}
    Let $X$ be a set, let $P$ be a poset, and let $P^P$ be the tautological $P$-complex (so $P^p = \mathrm{Cone}(p)$ for all~$p$).

    \begin{enumerate}
    \item 
    There is a bijective correspondence between $P$-complex structures on~$X$ and functions $m : X \to P$. The correspondence is defined as follows.

    \begin{itemize}
    \medskip
    \item
        Given a $P$-complex $X^P$, define its \emph{classifying map} $m(x) = \min P_x$.

    \medskip
    \item
        Given a function $m : X \to P$, let $X^P$ be the $m$-pullback of $P^P$.

    \end{itemize}

    \end{enumerate}

    \noindent
    For such $X^P$ and $m : X \to P$, consider a map $f : W \to X$ and a poset map $\phi : P \to Q$.

    \begin{enumerate}
    \setcounter{enumi}{1}
    \item 
    The classifying map of the $f$-pullback $(W^p)$ of $(X^p)$ is $m \circ f$.

    \medskip
    \item
    The classifying map of the $\phi$-pushforward $(X^q)$ of $(X^p)$ is $\phi \circ m$.
    \end{enumerate}

The word `complex' alludes to the following `cell decomposition' of a poset complex~$X^P$.

\begin{alignat*}{3}
&
\text{`closed cell'}
&\qquad&
X^p
&&=
\left\{ x \in X \mid m(x) \leqslant p \right\}
\\
&
\text{`open cell'}
&&
X^p - X^{\mathrm{Link}(p)}
&&= \left\{ x \in X \mid m(x) = p \right\}
\end{alignat*}

This becomes more meaningful when we consider topological poset complexes in Section~\ref{sec:topological-systems}.
Just as with CW-complexes, the `open' in `open cell' doesn't mean topologically open in~$X$.

\label{prop:cf-composition}
    A composite of cofibrations is a cofibration.
    \qed

\label{prop:cf-MV}
Let $U, V$ be closed subspaces of a topological space. If the inclusion $U \cap V \to V$ is a cofibration then the inclusion $U \to U \cup V$ is a cofibration.

\qed

Consider the special case $B = A \cup \{p\}$ where $p \in P-A$ is minimal. The map
    \[
    \xymatrix{
    X^{\mathrm{Link}(p)}
    =
    X^{A \cap \mathrm{Cone}(p)} 
    =
    X^A \cap X^{\mathrm{Cone}(p)}
    \ar[r]
    &
    X^{\mathrm{Cone}(p)}
    }
    \]
    is a cofibration by hypothesis, so the map
    \[
    \xymatrix{
    X^A
    \ar[r]
    &
    X^A \cup X^{\mathrm{Cone}(p)}
    =
    X^B
    }
    \]
    is a cofibration by Proposition~\ref{prop:cf-MV}. Now iterate this step using Proposition~\ref{prop:cf-composition}.

\label{prop:cf-product}

If the closed inclusions $U \to X$ and $V \to Y$ are cofibrations, then the closed inclusion $\big(U \times Y\big) \cup \big(X \times V\big) \to X \times Y$ is a cofibration.
\qed

These are closed complexes by Example~\ref{ex:closed}. We verify the cofibration property.

    (1) Subcomplex inclusions of simplicial complexes and CW-complexes are cofibrations \cite[Section~7.3, Example~5]{Brown_2006} so in particular each $X^{\mathrm{Link}(\alpha)} \to X^{\mathrm{Cone}(\alpha)} = X^{\alpha}$ is a cofibration.

    (2) Immediate.

    (3) Let $X^P, Y^Q$ be link-cofibrant complexes. For $(p,q) \in P \times Q$ the inclusions
    \[
    \xymatrix{
    X^{\mathrm{Link}(p)} \ar[r] & X^{\mathrm{Cone}(p)}
    }
    \quad
    \text{and}
    \quad
    \xymatrix{
    Y^{\mathrm{Link}(q)} \ar[r] & Y^{\mathrm{Cone}(q)}
    }
    \]
    are closed cofibrations by hypothesis.

    Now

    \begin{align*}
    \mathrm{Link}((p,q))
    &=
    \mathrm{Link}(p) \times \mathrm{Cone}(q)
    \cup
    \mathrm{Cone}(p) \times \mathrm{Link}(q)
    \\
    \mathrm{Cone}((p,q))
    &=
    \mathrm{Cone}(p) \times \mathrm{Cone}(q)
    \end{align*}

    therefore

    \begin{align*}
    (X \times Y)^{\mathrm{Link}((p,q))}
    &=
    X^{\mathrm{Link}(p)} \times Y^{\mathrm{Cone}(q)}
    \cup
    X^{\mathrm{Cone}(p)} \times Y^{\mathrm{Link}(q)}
    \\
    (X \times Y)^{\mathrm{Cone}((p,q))}
    &=
    X^{\mathrm{Cone}(p)} \times Y^{\mathrm{Cone}(q)}
    \end{align*}

    so the inclusion
    \[
    \xymatrix{
    (X \times Y)^{\mathrm{Link}((p,q))}
        \ar[r]
    &
    (X \times Y)^{\mathrm{Cone}((p,q))}
    }
    \]
    is a cofibration by Proposition~\ref{prop:cf-product}.

    (4) Let $X^Q$ be the $\phi$-pushforward of a link-cofibrant complex $X^P$. Each $X^{\mathrm{Link}(q)} \to X^{\mathrm{Cone}(q)}$ is an inclusion of subcomplexes of $X^P$ and hence a cofibration by Proposition~\ref{prop:cf-subcomplexes}.

(1) Each cone is contractible in the Alexandrov topology. Indeed, the map
    \[
    H : \mathrm{Cone}(p) \times [0,1] \longrightarrow \mathrm{Cone}(p)
    \]
    defined by
    \[
    H(q,t) = 
    \begin{cases}
        q & \text{for $t=0$}
        \\
        p & \text{for $t>0$}
    \end{cases} 
    \]
    is continuous, because for any closed set $A \leqslant P$ the preimage

    \[
    H^{-1}(A) =
    \begin{cases}
            A \times \{0\}
            & \text{if $A \neq P$ (equivalently $p \not \in A$)}
            \\
            \mathrm{Cone}(p) \times [0,1]
            & \text{if $A = P$}
    \end{cases}
    \]
    is closed. Thus $H$ is a homotopy from the identity map to the constant map~$p$.

    (2) Regular CW-complexes are normal \cite[Chapter~III, Theorem~2.1]{Lundell_Weingram_1969} so $X^\alpha = \overline{e_\alpha}$ for all $\alpha$. By regularity, each $\overline{e_\alpha}$ is a closed disk hence contractible.

    (3), (4) Immediate.

\label{prop:glued}
    Let $P$ be a poset, and suppose $P = A \cup B$ for closed sets $A, B \leqslant P$. Write $N = A \cap B$.

    Consider a poset system $(X^p)$ with $X^P = X$. Suppose $(X^a \mid a \in A)$ and $(X^b \mid b \in B)$ are separated and suppose $X^A \cap X^B = X^N$. Then $(X^p)$ is separated.

This is Proposition~\ref{prop:glued} with the $P$-system defined as follows:
    \begin{alignat*}{2}
    X^a &= Y^a &\quad &\text{for $a \in A$}
    \\
    X^b &= Z^b &\quad &\text{for $b \in B$}    
    \end{alignat*}
    The definition is consistent because $Y^n = Z^n$ for $n \in N$.

\label{prop:gluing-topological}
	In the situation of Corollary~\ref{cor:gluing}, suppose that $Y^A, Z^B$ are topological poset complexes, with $Y^N, Z^N$ closed subspaces, and the isomorphism $f : Y^N \to Z^N$ a homeomorphism. Assign to $X^P = Y^A \cup_f Z^B$ the quotient topology; that is, its topology as an adjunction space.

    Then each of the following adjectives applies to~$X^P$ if it applies to both $Y^A$ and $Z^B$.

    \[
    \text{
    {\rm(1)} closed
    \;
    {\rm(2)} link-cofibrant
    \;
    {\rm(3)} cellular
    \;
    {\rm(4)} compact
    \;
    {\rm(5)} Hausdorff
    }
    \]

\label{thm:contractibility}
    Under the hypotheses of Theorem~\ref{thm:carrier}, suppose further that $X$ is locally compact.\footnote{ 
        We take `locally compact' to mean that every point has a basis of compact neighbourhoods.
    }
    Endow the mapping space
    \[
    \mathrm{Map}(X,Y)
    =
    \{ \text{continuous maps $X \to Y$} \}
    \]
    with the compact-open topology.

    Then the subspaces\footnote{ 
    This notation suppresses the poset systems $(X^p), (Y^q)$ to reduce clutter.
    }

    \begin{align*}
        \mathrm{Map}_{\phi}(X,Y)
        &=
        \{ \text{continuous $\phi$-maps $X \to Y$} \}
        \\
        \mathrm{Map}_\phi(X,Y; f_A)
        &=
        \{ \text{continuous $\phi$-maps $X \to Y$ extending $f_A$} \}
    \end{align*}

    are contractible.

\label{prop:unique-H-class}
    Let $\phi: P \to Q$ be a map of finite posets. Suppose
    \[
    \xymatrix{
    X_1^P
        \ar[r]^{f_1}
    &
    Y_1^Q
    &
    X_2^P
        \ar[r]^{f_2}
    &
    Y_2^Q
    }
    \]
    are continuous $\phi$-maps of CL-complexes. Then $f_1, f_2$ are canonically homotopy equivalent in the following sense: given any continuous $P$-map $\xi : X_1^P \to X_2^P$ and any continuous $Q$-map $\eta : Y_1^Q \to Y_2^Q$, the diagram
    \[
    \xymatrix{
    X_1^P
        \ar[r]^{f_1}
        \ar[d]_{\xi}
    &
    Y_1^Q
        \ar[d]^{\eta}
    \\
    X_2^P
        \ar[r]_{f_2}
    &
    Y_2^Q
    }
    \]
    commutes up to homotopy. If one of $f_1, f_2$ is a homotopy equivalence, then so is the other.

\label{cor:conventions-agree}
    The CL-complex homotopy type of a finite poset is the same as its order-complex homotopy type. The CL-complex homotopy class of a map of finite posets is the same as its order-complex homotopy class.
    \qed

\label{construction:join}
    Identify $P$ with an affinely independent subset of a real vector space. Construct a poset system $(X^p)$ by defining
    \[
    X^p
    =
    \{ p \} \star \bigcup_{q < p} X^q
    =
    \{p\} \star X^{\mathrm{Link}(p)} 
    \]

    recursively with respect to the partial order,\footnote{ 
    Here $\star$ is the geometric join, with $A \star B$ being the union of line segments from $A$ to $B$.
    }

    and let $X = X^P$.

\label{thm:QTA-rel}
    Consider a diagram of finite posets:
    \[
    \xymatrix{
    P
        \ar[r]^-{\phi}
        \ar[dr]_-{\alpha}
    &
    Q
        \ar[d]^-{\beta}
    \\
    &
    R
    }
    \]
    Suppose the induced map of Quillen fibers $\alpha/r \longrightarrow \beta/r$ is a homotopy equivalence for all~$r$.

    Then $\phi$ is a homotopy equivalence.

We proceed by induction on the cardinality of $R$. The result is trivial if $R$ is empty.

    Suppose that $R$ is not empty and that the result has been proved for all posets of smaller cardinality.

    Let $a \in R$ be a maximal element and let $V$ be the V-shaped poset. 

    We have a poset map $\psi : R \to V$ defined as follows:
    \[
    \psi(r) =
    \begin{cases}
        1 &\text{if $r = a$}
        \\
        0 &\text{if $r \in \mathrm{Link}(a)$}
        \\
        2 &\text{if $r \in R - \mathrm{Cone}(a)$}
    \end{cases}
    \]

    The Quillen fibers of this map are:
    \begin{align*}
        \psi/1 &= \mathrm{Cone}(a)
        &
        \psi/0 &= \mathrm{Link}(a)
        &
        \psi/2 &= R - \{a\}
    \end{align*}

    Let $X^V, Y^V$ be the $\psi$-pushforwards of $X^R, Y^R$.

    These are link-cofibrant by Example~\ref{ex:LC}~(4), and we have:

    \begin{align*}
        X^1 &= X^{\mathrm{Cone}(a)} = X^a
        &
        X^0 &= X^{\mathrm{Link}(a)}
        &
        X^2 &= X^{R - \{a\}}
        \\
        Y^1 &= Y^{\mathrm{Cone}(a)} = Y^a
        &
        Y^0 &= Y^{\mathrm{Link}(a)}
        &
        Y^2 &= Y^{R - \{a\}}
    \end{align*}

    The map $f^1 = f^a : X^a \to Y^a$ is a homotopy equivalence by assumption, while $f^0, f^2$ are homotopy equivalences by the inductive hypothesis.

    The Homotopy Gluing Theorem~\ref{thm:gluing} implies that $f$ is a homotopy equivalance.

\label{thm:nerve}
    Let $\mathcal{U} = (U_i \mid i \in I)$ be a good tame cover in a topological space, with $I$ finite.

    Then $U^{\mathrm{all}}$ is the underlying space of a CL-complex for ${N}^{\mathrm{op}}$, and therefore homotopy equivalent to $|\mathrm{Nerve}(\mathcal{U})|$.

\label{prop:nerve-natural}
    Let $\mathcal{U} = (U_i \mid i \in I)$ and $\mathcal{V} = (V_j \mid j \in J)$ be good tame covers in topological spaces $X,Y$ with $I, J$ finite. Let $f : X \to Y$ be a continuous map.

    Suppose $\mathcal{U}$ is $f$-subordinate to $\mathcal{V}$ in the sense that there exists a function $\alpha : I \to J$ such that $f(U_i) \subseteq V_{\alpha(i)}$ for all $i \in I$.

    Then the diagram
    \[
    \xymatrix{
    U^{\mathrm{all}}
        \ar[rrr]_{\simeq}^{\mathbf{Theorem~\ref{thm:nerve}}}
        \ar[d]_-{f}
    &&&
    |N_\mathcal{U}|
        \ar[d]^-{|\phi_\alpha|}
    \\
    V^{\mathrm{all}}
        \ar[rrr]_{\simeq}^{\mathbf{Theorem~\ref{thm:nerve}}}
    &&&
    |N_\mathcal{V}|
    }
    \]
    commutes in the homotopy category. Here $\phi_\alpha : N_{\mathcal{U}} \to N_{\mathcal{V}}$ is the poset map induced by~$\alpha$ (compare Example~\ref{ex:poset-system-maps}(2)).

\label{ex:Sheehy-k}
    If we define
    \[
    K_k
    =
    \{
    \sigma \in \Delta(I)
    \mid
    \text{$\sigma$ has at least $k$ vertices}
    \}
    \]
    then $U^{K_k}$ is the $k$-covered region.

\label{thm:multi-nerve}
    Let $\mathcal{U} = (U_i \mid i \in I)$ be a good tame cover in a topological space, with $I$ finite. Let $K$ be a covering requirement.

    Then $U^K$ is the underlying space of a CL-complex for ${(K \cap N)}^{\mathrm{op}}$. It is homotopy equivalent to the induced subcomplex of $\mathrm{ord}(N)$ spanned by the vertices corresponding to the elements of~$K \cap N$.

\label{prop:multi-nerve-natural}
    Let $\mathcal{U} = (U_i \mid i \in I)$ and $\mathcal{V} = (V_i \mid i \in I)$ be good tame covers in topological spaces $X,Y$ with $I$ finite. Let $f : X \to Y$ be a continuous map such that $f(U_i) \subseteq V_{i}$ for all $i \in I$.

    Then, for any covering requirement $K$, the diagram
    \[
    \xymatrix{
    U^K
        \ar[rrr]_-{\simeq}^-{\mathbf{Theorem~\ref{thm:multi-nerve}}}
        \ar[d]_-{f}
    &&&
    |\mathrm{ord}(K \cap N_{\mathcal{U}})|
        \ar[d]^-{\text{\rm inclusion}}                 
    \\
    V^K
        \ar[rrr]_-{\simeq}^-{\mathbf{Theorem~\ref{thm:multi-nerve}}}
    &&&
    |\mathrm{ord}(K \cap N_{\mathcal{V}})|
    }
    \]
    commutes in the homotopy category.
